input.script:
const c = document.querySelector('input[name="my-colors"]'); c.value = '#2e86de'; c.dispatchEvent(new Event('input', {bubbles:true})); c.dispatchEvent(new Event('change', {bubbles:true}));
const r = document.querySelector('input[name="my-range"]'); r.value = '8'; r.dispatchEvent(new Event('input', {bubbles:true})); r.dispatchEvent(new Event('change', {bubbles:true}));
JSON.stringify({color: c.value, range: r.value});
